properties.Jolt Specification:
[
  {
    "operation": "shift",
    "spec": {
      "items": {
        "*": {
          // Gán nhãn ads_id và tracking ở cấp item
          "adsid": "[&1].ads_id",
          "traffic_source": "[&1].traffic_source",
          "search_item_tracking": "[&1].tracking_raw",

          "item_basic": {
            // Lấy itemid và shopid
            "itemid": "[&2].itemid",
            "shopid": "[&2].shopid",
            "name": "[&2].name",
            "catid": "[&2].catid",
            "ctime": "[&2].ctime",
            "brand": "[&2].brand",
            "shop_name": "[&2].shop_name",
            "shop_location": "[&2].shop_location",

            // Nhóm Giá và Giảm giá
            "price": "[&2].price",
            "price_before_discount": "[&2].price_before_discount",
            "show_discount": "[&2].discount_percent",

            // Nhóm Tín nhiệm
            "sold": "[&2].sold",
            "historical_sold": "[&2].historical_sold",
            "liked_count": "[&2].liked_count",
            "cmt_count": "[&2].cmt_count",
            "shopee_verified": "[&2].is_shopee_verified",
            "is_official_shop": "[&2].is_mall",

            // Rating chi tiết (Dùng &3 vì lồng thêm 1 cấp item_rating)
            "item_rating": {
              "rating_star": "[&3].rating_star",
              "rating_count": "[&3].rating_distribution"
            },

            // Video info (Dùng &4 vì lồng qua mảng video_info_list)
            "video_info_list": {
              "*": {
                "duration": "[&4].video_duration"
              }
            },

            // Voucher
            "voucher_info": {
              "label": "[&3].voucher_label"
            },

            // Phân loại sản phẩm (Gom vào mảng)
            "tier_variations": {
              "*": {
                "options": "[&4].variants[]"
              }
            },

            // Nhãn đặc trưng
            "label_ids": "[&2].label_ids"
          }
        }
      }
    }
  }
]

[
  {
    "operation": "shift",
    "spec": {
      "data": {
        "decoration": {
          "*": {
            // Sử dụng &1 để lấy chỉ số của component trong mảng decoration làm Key duy nhất
            "recommendations": {
              "centralize_item_card": {
                "item_cards": {
                  "*": {
                    "@": "flatten_map.recomm_&5_&1.item_data",
                    "#recommendation": "flatten_map.recomm_&5_&1.source_type"
                  }
                }
              }
            },
            "product_grid": {
              "centralize_item_card": {
                "item_cards": {
                  "*": {
                    "@": "flatten_map.grid_&5_&1.item_data",
                    "#product_grid": "flatten_map.grid_&5_&1.source_type"
                  }
                }
              }
            },
            "top_products": {
              "centralize_item_card": {
                "item_cards": {
                  "*": {
                    "@": "flatten_map.top_&5_&1.item_data",
                    "#top_products": "flatten_map.top_&5_&1.source_type"
                  }
                }
              }
            },
            "bundle_deal": {
              "bundle_deals": {
                "*": {
                  "centralize_item_card": {
                    "item_cards": {
                      "*": {
                        "@": "flatten_map.bundle_&7_&5_&1.item_data",
                        "#bundle_deal": "flatten_map.bundle_&7_&5_&1.source_type"
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  },
  {
    "operation": "shift",
    "spec": {
      "flatten_map": {
        "*": {
          // Bắt đầu đẩy vào mảng list không tên ở root
          "source_type": "[#2].source_type",
          "item_data": {
            "itemid": "[#3].itemid",
            "shopid": "[#3].shopid",
            "catid": "[#3].catid",
            "ctime": "[#3].ctime",
            "liked_count": "[#3].liked_count",
            "label_ids": "[#3].label_ids",
            "info": "[#3].ranking_score_raw",
            "item_card_display_price": {
              "price": "[#4].price",
              "original_price": "[#4].original_price",
              "discount": "[#4].discount",
              "recommended_shop_voucher_info": {
                "voucher_discount": "[#5].voucher_value"
              }
            },
            "item_card_display_sold_count": {
              "historical_sold_count_text": "[#4].sold_total",
              "monthly_sold_count_text": "[#4].sold_monthly"
            },
            "item_rating": {
              "rating_star": "[#4].rating_score"
            },
            "item_card_displayed_asset": {
              "name": "[#4].name"
            },
            "shop_data": {
              "shop_name": "[#4].shop_name",
              "shop_location": "[#4].shop_location"
            }
          }
        }
      }
    }
  }
]

[
  {
    "operation": "shift",
    "spec": {
      "data": {
        "centralize_item_card": {
          "item_cards": {
            "*": {
              // --- 1. NHÓM ĐỊNH DANH & PHÂN LOẠI (Core IDs) ---
              "itemid": "[&1].itemid",
              "shopid": "[&1].shopid",
              "catid": "[&1].catid",
              "item_type": "[&1].item_type",
              "ctime": "[&1].ctime",
              "label_ids": "[&1].label_ids",
              // --- 2. NỘI DUNG HIỂN THỊ (Content & Assets) ---
              "item_card_displayed_asset": {
                "name": "[&2].name",
                "image": "[&2].main_image",
                "image_overlay": {
                  "legacy_overlay": {
                    "name": "[&4].campaign_overlay_name"
                  }
                },
                "rating": {
                  "rating_text": "[&3].rating_display_small"
                }
              },
              "global_brand": {
                "display_name": "[&2].brand_name",
                "brand_id": "[&2].brand_id"
              },
              "video_info_list": {
                "*": {
                  "video_id": "[&3].video_ids[]",
                  "duration": "[&3].video_durations[]"
                }
              },
              "tier_variations": {
                "*": {
                  "name": "[&3].variation_names[]",
                  "options": "[&3].variation_options[]"
                }
              },
              // --- 3. TÀI CHÍNH & KHUYẾN MÃI (Economics) ---
              "item_card_display_price": {
                "price": "[&2].price",
                "strikethrough_price": "[&2].price_before_discount",
                "discount": "[&2].discount_percent",
                "promotion_id": "[&2].promotion_id",
                "recommended_shop_voucher_info": {
                  "voucher_code": "[&3].voucher_code",
                  "voucher_discount": "[&3].voucher_value",
                  "min_spend": "[&3].voucher_min_spend"
                }
              },
              // --- 4. HIỆU SUẤT & TÍN NHIỆM (Social Proof/Performance) ---
              "item_card_display_sold_count": {
                "historical_sold_count_text": "[&2].sold_total_text",
                "monthly_sold_count_text": "[&2].sold_monthly_text"
              },
              "item_rating": {
                "rating_star": "[&2].rating_star_full",
                "rating_count": "[&2].rating_count_list"
              },
              "liked_count": "[&1].liked_count",
              "shopee_verified": "[&1].is_verified",
              "shop_data": {
                "shop_name": "[&2].shop_name",
                "shop_location": "[&2].shop_location"
              },
              // --- 5. TÍN HIỆU HỆ THỐNG & AI (System Signals) ---
              "info": "[&1].system_info_raw",
              "is_adult": "[&1].is_adult",
              "is_sold_out": "[&1].is_sold_out",
              "status": "[&1].item_status_code",
              "adsid": "[&1].ads_id",
              "campaign_id": "[&1].campaign_id"
            }
          }
        }
      }
    }
  }
]
